<script setup>
import {computed,onMounted,ref} from 'vue'
import {Skeleton} from 'ant-design-vue'
import {Database,FileText,Image,LayoutTemplate,FileUp,Plus,ArrowRight,Bot,Activity,BookOpen} from '../icons'
import {api,can,sessionUser} from '../api'
import {labelOf,dateTime,fileSize} from '../ui'
import {embeddingLabel} from '../retrieval'
const data=ref(null),reports=ref([]),runtime=ref(null),error=ref(''),loading=ref(true),reportError=ref('')
const assets=computed(()=>data.value?[{name:'知识库',value:data.value.counts.knowledge_bases,icon:Database,path:'/knowledge'},{name:'文档',value:data.value.counts.documents,icon:FileText,path:'/documents'},{name:'图片内容',value:data.value.counts.images,icon:Image,path:'/documents'},{name:'模板版本',value:data.value.counts.templates,icon:LayoutTemplate,path:'/report-templates',visible:can('reports.generate')}].filter(x=>x.visible!==false):[])
const currentReports=computed(()=>reports.value.filter(r=>r.document_state!=='archived'))
const drafts=computed(()=>reports.value.filter(r=>!['finalized','archived'].includes(r.document_state)))
const activeJobs=computed(()=>runtime.value?(runtime.value.queue.counts.queued||0)+(runtime.value.queue.counts.running||0):null)
const totalContent=computed(()=>data.value?.modalities.reduce((sum,item)=>sum+item.value,0)||0)
async function load(){loading.value=true;error.value='';reportError.value='';const results=await Promise.allSettled([api('/api/dashboard'),can('reports.generate')?api('/api/report-tasks'):Promise.resolve([]),can('ops.read')?api('/api/operations'):Promise.resolve(null)]);if(results[0].status==='fulfilled')data.value=results[0].value;else error.value=results[0].reason.message;if(results[1].status==='fulfilled')reports.value=results[1].value;else reportError.value=results[1].reason.message;if(results[2].status==='fulfilled')runtime.value=results[2].value;loading.value=false}
onMounted(load)
</script>
<template><div class="page-stack dashboard-page">
 <div class="page-intro"><div><h2>工作台</h2><p>欢迎回来，{{sessionUser?.name}}。从这里继续你的知识工作。</p></div><button class="secondary-button" :disabled="loading" @click="load">刷新概览</button></div>
 <section class="quick-start card"><div class="quick-start-copy"><span class="section-kicker">开始工作</span><h3>把资料变成有依据的答案</h3><p>上传资料，选择知识库，即可开始问答或编制报告。</p></div><div class="quick-start-actions"><router-link v-if="can('kb.write')" class="primary-button" to="/documents?upload=1"><FileUp :size="16"/>上传文档</router-link><router-link v-if="can('qa.use')" class="secondary-button" to="/chat"><Bot :size="16"/>开始问答</router-link><router-link v-if="can('reports.generate')" class="secondary-button" to="/reports/new"><Plus :size="16"/>新建报告</router-link></div></section>
 <div v-if="error" class="error-banner" role="alert">{{error}} <button class="text-button" @click="load">重新加载</button></div>
 <Skeleton v-if="loading&&!data" active :paragraph="{rows:5}"/>
 <template v-if="data">
  <div class="stat-grid"><router-link v-for="item in assets" :key="item.name" :to="item.path" class="stat-card asset-card" :title="item.name==='模板版本'?'包含历史版本；已发布模板请到模板库查看':item.name"><div><span>{{item.name}}</span><strong>{{item.value}}</strong></div><div class="stat-icon"><component :is="item.icon" :size="20"/></div></router-link></div>
  <div class="dashboard-columns">
   <section v-if="can('reports.generate')" class="card"><div class="card-heading"><h3>最近报告 <span class="badge">{{currentReports.length}}</span></h3><router-link class="text-button" to="/reports">全部报告<ArrowRight :size="14"/></router-link></div><div v-if="reportError" class="error-banner">{{reportError}}</div><div v-if="currentReports.length" class="recent-list"><router-link v-for="r in currentReports.slice(0,5)" :key="r.id" :to="'/reports/'+r.id" class="recent-row"><span class="file-tile"><BookOpen :size="18"/></span><span class="recent-copy"><strong>{{r.title}}</strong><small>{{r.knowledge_base_name}} · {{dateTime(r.updated_at||r.created_at)}}</small></span><span class="badge" :class="r.document_state==='finalized'?'green':'blue'">{{labelOf(r.document_state||'draft')}}</span></router-link></div><div v-else-if="!reportError" class="empty"><BookOpen :size="26"/><p>暂无未归档报告，可从模板开始创建。</p><router-link class="text-button" to="/reports/new">新建报告</router-link></div></section>
   <section class="card"><div class="card-heading"><h3>待办与运行</h3><Activity :size="17"/></div><div class="attention-list"><router-link v-if="can('reports.generate')" class="attention-row" to="/reports"><span><strong>继续编写与审阅</strong><small>你的未归档、未定稿报告</small></span><b>{{drafts.length}}</b></router-link><router-link v-if="can('ops.read')" class="attention-row" to="/operations"><span><strong>后台任务</strong><small>{{activeJobs===null?'暂未取得运行状态':activeJobs?'后台处理中，可离开页面':'当前没有排队或执行中的任务'}}</small></span><b>{{activeJobs??'—'}}</b></router-link><p v-if="!can('reports.generate')&&!can('ops.read')" class="muted">可从文档管理或知识问答开始工作。</p></div></section>
  </div>
  <section class="card"><div class="card-heading"><h3>最近入库文档</h3><router-link class="text-button" to="/documents">全部文档<ArrowRight :size="14"/></router-link></div><div v-if="data.recent_documents.length" class="table-wrap"><table class="data-table"><thead><tr><th>文档名称</th><th>内容类型</th><th>状态</th><th>大小</th><th></th></tr></thead><tbody><tr v-for="doc in data.recent_documents" :key="doc.id"><td><router-link :to="'/documents/'+doc.id" class="table-title">{{doc.name}}</router-link></td><td>{{labelOf(doc.modality)}}</td><td><span class="badge" :class="doc.status==='ready'?'green':'amber'">{{labelOf(doc.status)}}</span></td><td>{{fileSize(doc.size)}}</td><td><router-link :to="'/documents/'+doc.id" class="text-button">查看</router-link></td></tr></tbody></table></div><div v-else class="empty">暂无入库文档，上传后可在这里查看处理结果。</div></section>
  <details class="card system-summary"><summary>系统与知识资产概况 <span class="muted">模型配置、检索方式和内容分布</span></summary><div class="summary-body"><div class="metric-list"><div class="metric"><strong>{{data.model.configured?'已配置':'未配置'}}</strong><span>{{data.model.model}} · 不代表实时连通</span></div><div class="metric"><strong>{{embeddingLabel(data.model.embedding)}}</strong><span>实际向量后端</span></div><div class="metric"><strong>BM25 / RRF</strong><span>关键词与混合检索</span></div><div class="metric"><strong>未评测</strong><span>检索质量需用标注数据评估</span></div></div><div class="modality-list"><div v-for="item in data.modalities" :key="item.name" class="modality-row"><span>{{labelOf(item.name)}}</span><div class="progress-track"><div class="progress-value" :style="{width:(totalContent?item.value/totalContent*100:0)+'%'}"/></div><span>{{item.value}} · {{totalContent?Math.round(item.value/totalContent*100):0}}%</span></div></div><router-link v-if="can('settings.manage')" class="text-button" to="/settings">前往配置与连接检测<ArrowRight :size="14"/></router-link></div></details>
 </template>
</div></template>
<style scoped>
.quick-start{padding:22px 24px;display:flex;align-items:center;justify-content:space-between;gap:20px;background:linear-gradient(110deg,#fff 30%,#f0f6ff);border-color:#dce8f9}.section-kicker{font-size:11px;letter-spacing:.08em;color:#1677ff}.quick-start h3{font-size:21px;margin:5px 0 7px;font-weight:600;letter-spacing:-.02em}.quick-start p{font-size:12px;color:#626b79;margin:0}.quick-start-actions{display:flex;gap:8px;flex-wrap:wrap}.asset-card{color:inherit;text-decoration:none}.asset-card:hover{border-color:#b9d5ff;text-decoration:none}.dashboard-columns{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(260px,1fr);gap:18px}.recent-list{padding:0 20px}.recent-row{padding:14px 0;border-bottom:1px solid #f0f2f5;display:flex;align-items:center;gap:12px;color:inherit;text-decoration:none}.recent-row:last-child{border:0}.recent-row:hover .recent-copy strong{color:#1677ff}.file-tile{width:34px;height:38px;background:#f0f5ff;color:#6298e3;border-radius:6px;display:grid;place-items:center;flex-shrink:0}.recent-copy{min-width:0;flex:1;display:grid;gap:4px}.recent-copy strong{font-size:13px;font-weight:500;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.recent-copy small{font-size:11px;color:#8a929f;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.attention-list{padding:0 20px}.attention-row{display:flex;justify-content:space-between;align-items:center;padding:17px 0;color:inherit;border-bottom:1px solid #f0f2f5}.attention-row:last-child{border:0}.attention-row:hover{text-decoration:none}.attention-row span{display:grid;gap:5px}.attention-row strong{font-size:13px;font-weight:500}.attention-row small{font-size:11px;color:#8a929f}.attention-row b{font-size:25px;color:#1677ff;font-weight:500}.system-summary{padding:16px 20px}.system-summary summary{font-size:13px;cursor:pointer;font-weight:500}.system-summary summary .muted{font-weight:400;margin-left:10px}.summary-body{display:grid;gap:20px;margin-top:22px}.modality-list{max-width:600px}.modality-row{display:grid;grid-template-columns:60px 1fr 90px;align-items:center;gap:12px;padding:6px 0;font-size:12px;color:#626b79}.progress-track{height:5px;background:#f0f3f8;border-radius:3px;overflow:hidden}.progress-value{height:100%;background:#78aaf2}
@media(max-width:1100px){.quick-start{align-items:flex-start;flex-direction:column}.dashboard-columns{grid-template-columns:1fr}}@media(max-width:767px){.quick-start{padding:18px}.quick-start h3{font-size:18px}.quick-start-actions{width:100%}.quick-start-actions a{flex:1;padding:7px 8px;min-width:112px}.system-summary summary .muted{display:block;margin:5px 0 0 16px}.dashboard-columns{gap:16px}.recent-list,.attention-list{padding:0 16px}}
</style>

